#!/usr/bin/env python3
"""Current comparisons and source build records in the existing offline report style."""
import datetime,html,json,pathlib,re,sys,os
OLD=pathlib.Path('/tmp/lilscript-page-refresh-20260910');RUN=pathlib.Path('/tmp/lilscript-source-performance-20260910');OUT=pathlib.Path('/home/azureuser/lilscript/report-library-drift.html');pub=json.loads(pathlib.Path(os.environ.get('PUBLICATIONS_FILE',OLD/'publications.json')).read_text());e=html.escape
css=re.search(r'<style>([\s\S]*?)</style>',OUT.read_text())[1]
rows=[]
for n,p in sorted(pub.items()):
 root=pathlib.Path(p['path']);site=root/('web' if n=='vuelil' else 'site');d=json.loads((site/'comparison.json').read_text());source=json.loads((site/'source-build.json').read_text());rows.append({'name':n,'comparison':d,'sourceBuild':source,'publication':p})
motion_root=pathlib.Path(pub['motionlil']['path'])
perf=json.loads((motion_root/'site/performance.json').read_text())
motion_validation=json.loads((motion_root/'comparison/runtime-investigation/validation.json').read_text())
