assert all(perf['inputs'][lane]['sha256']==motion_comparison['esm'][lane]['sha256'] for lane in ['original','lilscript'])
assert all(x['status']=='measured' and x['validation']['backendAgreement'] for x in perf['workloads'])
native=sum(x['comparison']['sourceBuild']['original']['complete'] for x in rows);lil=sum(x['comparison']['buildComplete'] for x in rows);checks=sum(x['sourceBuild']['status']=='complete' for x in rows);live=sum(x['publication'].get('deployment')=='success' for x in rows)
def number(x):return f'{x:,}' if isinstance(x,(int,float)) else '—'
def sec(x):return f'{x:.3f}' if isinstance(x,(int,float)) and x<1 else f'{x:.2f}' if isinstance(x,(int,float)) else '—'
def duration(d):return sec(d['medianSeconds']) if d['complete'] else 'Failed ('+sec(d['samples'][-1]['wallSeconds'])+' s)' if d['samples'] else 'Unavailable'
table=[];cards=[]
for row in rows:
 n=row['name'];d=row['comparison'];s=row['sourceBuild'];timing=d['sourceBuild'];a=d['esm'].get('lilscript') or {};b=d['esm']['original'];status='verified' if s['status']=='complete' else 'blocked';ratio=f"{a['brotli11']/b['brotli11']:.3f}×" if a else '—';state='live' if row['publication'].get('deployment')=='success' else 'deploying'
 table.append(f'<tr data-name="{n}" data-status="{status}"><th><a href="#{n}">{n}</a></th><td>{number(a.get("brotli11"))}</td><td>{number(b["brotli11"])}</td><td>{ratio}</td><td>{duration(timing["lilscript"])}</td><td>{duration(timing["original"])}</td><td><span class="badge {status}">{"checks pass" if status=="verified" else "incomplete"}</span></td><td>{state}</td></tr>')
 m=d['machine'];o=d['upstream'];port=s['portSource'];command=' '.join(timing['original']['samples'][0]['command']);samples=''.join(f'<tr><th>{lane}</th><td>{i+1}</td><td>{sec(sample["wallSeconds"])}</td><td>{sec(sample["cpuSeconds"])}</td><td>{sample["exitCode"]}</td></tr>' for lane,key in [('LilScript','lilscript'),('Original','original')] for i,sample in enumerate(timing[key]['samples']))
 note=d['compatibility']
 if n=='monacolil':note='LilScript build failed parser admission: generated JavaScript contained an unexpected token. Original source build succeeded. The port has partial API coverage.'
 if n=='vuelil':note='LilScript runtime-core build failed a callable ABI check. Original Vue source build succeeded. Full LilScript ESM is unavailable.'
 if n=='solidlil':note+=' The implementation covers only part of the original API.'
 cards.append(f'''<article class="card" id="{n}" data-name="{n}" data-status="{status}"><div class="card-head"><h2>{n}</h2><span class="badge {status}">{"checks pass" if status=="verified" else "incomplete"}</span></div><p>{e(note)}</p><p class="links"><a href="https://yeargun.github.io/{n}/">Comparison page</a> · <a href="https://github.com/yeargun/{n}/commit/{row['publication']['commit']}">Published repository</a> · <a href="{e(o['repository'].removesuffix('.git'))}/commit/{o['commit']}">Original source</a></p><div class="two"><div><h3>Current ESM</h3><p>{e(o['package'])} {e(o['version'])} · original commit <code>{o['commit']}</code><br>LilScript compiler <code>{d['compiler']['commit']}</code><br>Port source <code>{port['commit']}</code></p><dl><dt>LilScript raw / gzip / Brotli bytes</dt><dd>{number(a.get('raw'))} / {number(a.get('gzip9'))} / {number(a.get('brotli11'))}</dd><dt>Original raw / gzip / Brotli bytes</dt><dd>{number(b['raw'])} / {number(b['gzip9'])} / {number(b['brotli11'])}</dd></dl><p>{e(d['scope'])}</p></div><div><h3>Source builds</h3><p>Azure {e(m['instanceClass'])}<br>{e(m['cpu'])}<br>{m['logicalCpus']} vCPUs · {m['memoryBytes']/2**30:.1f} GiB · {e(m['os'])}<br>Node {e(m['node'])}</p><p>LilScript package median: <strong>{duration(timing['lilscript'])} s</strong><br>Original repository median: <strong>{duration(timing['original'])} s</strong><br>Native-toolchain ESM assembly median: {sec(d['build']['originalEsmSeconds'])} s</p></div></div><p class="scope">{e(timing['scopeNote'])}</p><details><summary>Commands, individual samples and exact evidence</summary><p>Original command: <code>{e(command)}</code><br>LilScript command: <code>{e(d['build']['packageScope'])}</code></p><p>{e(s.get('prerequisiteAdjustments') or 'No extra development dependency pins were required.')}</p><div class="table-wrap"><table><thead><tr><th>Lane</th><th>Run</th><th>Wall seconds</th><th>CPU seconds</th><th>Exit code</th></tr></thead><tbody>{samples}</tbody></table></div><pre>{e(json.dumps(s,indent=2))}</pre></details></article>''')
performance_rows=[]
for row in perf['workloads']:
 if row['status']!='measured':performance_rows.append(f'<tr><th>{e(row["label"])}</th><td colspan="5">Behavior mismatch; no speed score.</td></tr>');continue
 s=row['summary'];o=s['original'];l=s['lilscript'];performance_rows.append(f'<tr><th>{e(row["label"])}</th><td>{o["mainThreadMs"]:.2f}</td><td>{l["mainThreadMs"]:.2f}</td><td>{s["cpuRatio"]:.3f}×</td><td>{s["cpuRatio95"][0]:.3f}–{s["cpuRatio95"][1]:.3f}</td><td>{"Within ±5%" if s["withinFivePercent"] else "Different CPU cost"}</td></tr>')
compiler_revisions=sorted({x['comparison']['compiler']['commit'] for x in rows})
compiler_links=' · '.join(f'<a href="https://github.com/yeargun/lilscript/commit/{revision}">{revision[:8]}</a>' for revision in compiler_revisions)
measured=[x for x in perf['workloads'] if x['status']=='measured']
waapi=[x for x in measured if x['api']=='animateMini']
performance_notes=[f"{sum(x['summary']['withinFivePercent'] for x in waapi)} of {len(waapi)} WAAPI cases meet the ±5% renderer-CPU equivalence criterion."]
for name,label in [('animate-xy-128','x/y'),('animate-layout-128','Layout'),('motion-values-128','MotionValue')]:
 work=next((x for x in measured if x['id']==name),None)
 if work:
  ratio=work['summary']['cpuRatio'];performance_notes.append(f"{label} uses {abs(ratio-1)*100:.1f}% {'more' if ratio>1 else 'less'} renderer CPU in this workload.")
performance_note=' '.join(performance_notes)
full=motion_comparison['esm']['lilscript'];original=motion_comparison['esm']['original'];default=motion_comparison['defaultEntry']
cost_note=f"""<p><strong>Current size.</strong> The matched 312-export Motionlil graph is {full['raw']:,} raw bytes and {full['brotli11']:,} Brotli bytes; original Motion is {original['raw']:,} raw and {original['brotli11']:,} Brotli bytes. The full port still misses the smaller-bundle goal. The default port entry is a narrower consumer API at {default['raw']:,} raw and {default['brotli11']:,} Brotli bytes, so its size is listed separately.</p>"""
structural_note=f"""<h3>Compiler and implementation findings</h3><p>Ordinary LilScript type annotations are compile-time information and do not add runtime validation. Explicit source type tests and conversions retain runtime semantics. The port still contains more explicit dynamic guards and JavaScript boundary adapters than original Motion; static typing has removed redundant guards from control options, callbacks, numeric state and value types. Remaining size and CPU differences are not explained solely by the DOM/CSSOM bottleneck.</p><p>The current package compiles one shared graph. Feature imports share constructors, caches and frame queues; native controls use shared prototype methods. Checked pure factories support removal of unused initialization. Completion promises, caller-owned keyframe arrays, option getters and null/undefined handling follow the checked original contracts.</p><p>Compiler regressions preserve native-class helpers and callback variables captured inside template expressions. Higher JavaScript optimization settings are evaluated separately from the measured production configuration, which uses level 0 plus the same recorded Terser pipeline. The compiler has {motion_structure['tests']['compilerLibrary']:,} passing library tests locally. These checks do not establish complete API parity: low-level layout/rendering adapters remain incomplete.</p>"""
mangling_rows=[]
for scope,label in [('full','Public ESM · 312 exports'),('consumer-api','Shared API · 50 exports'),('closed-app','Closed app · identical caller'),('closed-full','Closed diagnostic · 312 roots + caller')]:
 for mode in ['identifiers','closed-properties' if scope.startswith('closed') else 'public-properties']:
  pair={lane:next(x for x in motion_mangling['measurements'] if (x['scope'],x['mode'],x['lane'])==(scope,mode,lane)) for lane in ['original','lilscript']};o=pair['original'];l=pair['lilscript']
  mangling_rows.append(f'<tr><th>{label}<br>{"Identifiers" if mode=="identifiers" else "Identifiers + properties"}</th><td>{o["raw"]:,}</td><td>{l["raw"]:,}</td><td>{o["brotli11"]:,}</td><td>{l["brotli11"]:,}</td><td>{l["brotli11"]/o["brotli11"]:.3f}×</td></tr>')
mangling_note='<h3>Matched mangling and scope</h3><p>Both lanes use esbuild 0.28.1, Terser 5.51.2, ES2022 and three compression passes. Every property-mangled pair uses identical reservations. Public builds reserve public API, browser and dynamic names. Closed builds transform the same caller with the library and reserve browser/dynamic protocols; other properties can be renamed. The full closed diagnostic also retains all 312 roots under identical short export aliases. Closed sizes include the caller and are not public ESM distributions.</p><div class="table-wrap"><table><thead><tr><th>Scope / mangling</th><th>Motion raw</th><th>LilScript raw</th><th>Motion Br</th><th>LilScript Br</th><th>Br ratio</th></tr></thead><tbody>'+''.join(mangling_rows)+'</tbody></table></div><p>Each 312-export public mode passes 39 browser checks against the original with unchanged property names. All 72 closed comparisons match their checked values, native timing and RAF behavior. The public mix overload now supports the original two-argument mixer and three-argument numeric forms. These tests cover selected scenarios; low-level layout/rendering adapters remain incomplete. The gap persists under identical mangling policies. Earlier measurements used different esbuild/Terser versions and different property rules; this corrected comparison still shows real port overhead. The other 26 library cards retain their recorded measurements and pins.</p>'
assembly=motion_comparison['comparisonAssembly']['timings']
mangling_note+=f"<p>The headline bundle/minify assembly took {sum(assembly['original'].values()):.3f} s for Motion and {sum(assembly['lilscript'].values()):.3f} s for LilScript on the recorded worker (one assembly sample each). These are separate from the three clean native package-build timings.</p>"
generated=datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC');evidence={'generatedAt':generated,'libraries':rows,'motionPerformance':perf,'motionBehaviorValidation':motion_validation,'motionStructuralFix':motion_structure,'motionMangling':motion_mangling};payload=json.dumps(evidence,ensure_ascii=False).replace('<','\\u003c')
doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LilScript library comparisons and source build times</title><style>'''+css+'''</style></head><body>'''+f'''<header><p class="eyebrow">LilScript · current library comparisons</p><h1>Library comparisons<br>and source build times.</h1><p class="lede">Current LilScript ESM versus the matching original library, built from pinned Git sources. The comparison pages retain their existing designs and themes.</p><p class="stamp">{generated} · Recorded compiler revisions (each card retains its measurement pin): {compiler_links}</p><div class="stats"><div class="stat"><strong>{native}/27</strong><span>original source builds completed</span></div><div class="stat"><strong>{lil}/27</strong><span>LilScript package builds completed</span></div><div class="stat"><strong>{checks}/27</strong><span>recorded repository checks pass</span></div><div class="stat"><strong>{live}/27</strong><span>Pages deployments verified</span></div></div></header><main><section class="method"><h2>Build protocol</h2><p>Three builds per implementation on the same Azure worker, with alternating order and generated outputs cleared. Installed dependencies are reused; installation is timed separately and excluded from the build figures. The original command compiles its Git checkout using its native build tools. For packages authored in JavaScript, this can include generated declarations and type checks. Production ESM assembly is an additional, separately measured step.</p><p>The workers are Azure Standard_D16als_v7 machines, AMD EPYC 9V45, 16 vCPUs, 31.3 GiB RAM, Ubuntu 24.04.4 and Node 24.11.1. They belong to a shared pool; wall times include possible contention. Package output scopes differ, so these figures are not presented as build speedup ratios. The PostHog and PlayCanvas ports cover selected portions of their upstream repositories.</p><p>Monaco and Vue do not complete with the measured compiler. React Markdown has a dependency declaration failure after its runtime tests pass; Remark has a failing closed-entry check. Those limitations remain explicit. Passing recorded checks does not establish complete API parity for partial implementations.</p></section><section class="method" id="motion-performance"><h2>Motion browser performance</h2><p>Thirty paired trials per passing workload after two warmups per lane. Both sides use identical visible elements, CSS, keyframes, easing, duration and viewport. Every element is checked at five paused positions and at completion. Native animation calls, options and active properties must match before timing; additional natural-playback checks inspect every animated property on every element to verify continuous progress. The exact 312-export ESM graphs, using the same minifier versions and public extern reservations, are used for both size and performance; the native 52-export default port entry is recorded separately.</p><p><strong>Behavior contract.</strong> Native eligibility, string/color interpolation, easing, repeat timing, controls, interruption and library frame scheduling are compared with the source-built original. Apparent style/layout savings alone cannot establish matching behavior. The remaining CPU differences below apply to the checked workloads.</p>{cost_note}{mangling_note}{structural_note}<div class="table-wrap"><table><thead><tr><th>Workload</th><th>Motion CPU ms</th><th>LilScript CPU ms</th><th>Lil / Motion</th><th>95% interval</th><th>Result</th></tr></thead><tbody>{''.join(performance_rows)}</tbody></table></div><p>{performance_note} Script/style costs are recorded separately in the full table. The {motion_validation["browser"]["passed"]} browser regression checks cover backends, interpolation, easing, controls, interruption and scheduling. All seven workloads pass the sampled-value and backend checks, including string transforms. The rewrite is expected to preserve Motion behavior; a lower CPU figure is not evidence of better animation behavior. These checks cover the documented scenarios rather than every Motion API.</p><p class="small">CPU means Chromium main-thread TaskDuration in an 800 ms observation window for a 600 ms animation. Medians and paired bootstrap intervals are recorded; ratios are not simply ratios of the displayed medians. Headless Chromium {e(perf['browser'])}; 1280×900, DPR 1; the same Azure machine class above. Bundle loading and initial DOM setup are excluded. The reported frame cadence comes from the benchmark observer. Library RAF activity is recorded separately outside the timing interval; deterministic regression checks cover callback order, pause, seek, replay, reverse, stop and interruption. Headless renderer CPU does not include all GPU/compositor work. <a href="https://yeargun.github.io/motionlil/#performance">Full table, methodology and raw samples</a>.</p></section><section><h2>All libraries</h2><p>Brotli sizes are bytes. Build times are median wall seconds; failed attempts are labelled. Original ESM uses Terser; individual pages also show their explicitly labelled minifier alternatives.</p><div class="toolbar"><input id="filter" type="search" placeholder="Filter libraries" aria-label="Filter libraries"><select id="status" aria-label="Filter result"><option value="all">All results</option><option value="verified">Checks pass</option><option value="blocked">Incomplete</option></select><button id="download">Download evidence JSON</button><button onclick="window.print()">Print / PDF</button></div><div class="table-wrap"><table><thead><tr><th>Library</th><th>LilScript Br</th><th>Original Br</th><th>Byte ratio</th><th>LilScript build s</th><th>Original build s</th><th>Checks</th><th>Page</th></tr></thead><tbody>{''.join(table)}</tbody></table></div></section>{''.join(cards)}</main><footer>This report and its embedded evidence work offline. External repository and page links require a network connection. Raw build logs, dependency locks and compiler/source hashes are recorded in each repository under comparison/source-build.</footer><script id="evidence" type="application/json">{payload}</script>'''+'''<script>const evidence=JSON.parse(document.getElementById('evidence').textContent),filter=document.getElementById('filter'),status=document.getElementById('status');function apply(){for(const el of document.querySelectorAll('[data-name]'))el.hidden=!(el.dataset.name.includes(filter.value.toLowerCase())&&(status.value==='all'||el.dataset.status===status.value))}filter.addEventListener('input',apply);status.addEventListener('change',apply);document.getElementById('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(evidence,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='lilscript-source-build-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});</script></body></html>'''
OUT.write_text(doc);print(f'{OUT}: {native} original builds, {lil} LilScript builds, {checks} gates, {live} Pages deployments')
